"""Settings for Client, Pro and Admin: account, billing, sign-in email, password, two-factor on/off, notifications, theme, data export, closure request."""
import os
from playwright.sync_api import sync_playwright
def opt(p, sel, val):
    if p.locator(sel).count(): p.fill(sel, val)
def optc(p, sel):
    if p.locator(sel).count(): p.check(sel)
HERE = os.path.dirname(os.path.abspath(__file__)); OUT = os.path.join(HERE, 'out'); os.makedirs(OUT, exist_ok=True)
APP = 'file://' + os.path.join(HERE, '..', 'dist', 'listd-platform.html')
errs = []; n = [0]
def log(m): n[0] += 1; print(n[0], m, flush=True)
with sync_playwright() as pw:
    br = pw.chromium.launch(); p = br.new_page(viewport={'width': 1280, 'height': 900}, accept_downloads=True)
    p.on('pageerror', lambda e: errs.append(str(e)))
    W = lambda ms=300: p.wait_for_timeout(ms)
    h1 = lambda: p.locator('.a-main h1').first.inner_text()
    toast = lambda: p.locator('#toast').inner_text()
    def shot(name): p.screenshot(path=os.path.join(OUT, name + '.png'), full_page=True)
    def tab(t): p.click('.a-settab[data-tab=%s]' % t); W()
    def role(r): p.click('[data-act=role][data-r=%s]' % r); W()
    def signup(name, email, pwd):
        p.click('[data-act=auth-mode][data-m=signup]'); W(); opt(p, '#au-name', name); p.fill('#au-email', email); p.fill('#au-password', pwd); opt(p, '#au-confirm', pwd); optc(p, '#au-terms'); p.click('form[data-form=auth-signup] button[type=submit]'); W(1500)
    p.goto(APP); W(600)
    signup('Ada Okafor', 'ada@example.test', 'Listd2026!')
    p.click('label.a-opt:has(input[value=ESTATE_AGENT])'); p.check('input[name=authority]'); p.click('form[data-form=cl-ob1] button[type=submit]'); W()
    p.fill('#ob-org', 'Okafor Lettings'); p.click('form[data-form=cl-ob2] button[type=submit]'); W()
    p.fill('#ob-ba', '1 Test Road'); p.fill('#ob-bc', 'Bath'); p.fill('#ob-bp', 'BA1 1AA'); p.click('form[data-form=cl-ob3] button[type=submit]'); W()
    p.fill('#p-lbl', 'Flat 3'); p.fill('#p-addr', '22 Pulteney St, Bath'); p.fill('#p-pc', 'BA2 4DS'); p.fill('#p-cn', 'Jo'); p.fill('#p-cp', '07700900001'); p.click('form[data-form=prop] button[type=submit]'); W(); p.click('[data-act=cl-ob-finish]'); W()
    p.click('.a-side [data-go=settings]'); W(); log('client settings tabs: ' + ', '.join(p.locator('.a-settab').all_inner_texts())); shot('s1-account')
    p.fill('#st-phone', '07700 900123'); p.click('form[data-form=set-account] button[type=submit]'); W(); log('account: ' + toast() + ' phone=' + p.evaluate('me().phone'))
    tab('billing'); p.fill('#sb-c', 'Bristol'); p.click('form[data-form=set-billing] button[type=submit]'); W(); log('billing: ' + p.evaluate('me().billing.city'))
    tab('security'); shot('s2-security')
    p.fill('#se-new', 'ada@okafor.test'); p.fill('#se-pw', 'wrong'); p.click('form[data-form=set-email] button[type=submit]'); W(800); log('email wrong pw: ' + toast())
    p.fill('#se-new', 'ada@okafor.test'); p.fill('#se-pw', 'Listd2026!'); p.click('form[data-form=set-email] button[type=submit]'); W(1200); log('email: ' + toast())
    p.click('label.ld-switch:has([data-twofa])'); W(); shot('s3-2fa-setup'); log('2FA setup panel: %s' % bool(p.locator('form[data-form=mfa-on]').count()))
    p.fill('#mf-code', '000000'); p.click('form[data-form=mfa-on] button[type=submit]'); W(600); log('bad code: ' + toast())
    secret = p.evaluate('S.mfaSetup.secret'); p.fill('#mf-code', p.evaluate('s => totp(s)', secret)); p.click('form[data-form=mfa-on] button[type=submit]'); W(800); log('2FA on: ' + toast() + ' | switch=' + str(p.locator('[data-twofa]').is_checked()))
    p.click('.a-top [data-act=signout]'); W(); p.fill('#au-email', 'ada@okafor.test'); p.fill('#au-password', 'Listd2026!'); p.click('form[data-form=auth-signin] button[type=submit]'); W(1200); log('sign-in asks: ' + h1())
    p.fill('#au-code', p.evaluate('s => totp(s)', secret)); p.click('form[data-form=auth-mfa] button[type=submit]'); W(900); log('after code: ' + h1())
    p.click('.a-side [data-go=settings]'); W(); tab('security'); p.click('label.ld-switch:has([data-twofa])'); W(); log('turn-off asks password: %s' % bool(p.locator('form[data-form=mfa-off]').count()))
    p.fill('#mo-pw', 'Listd2026!'); p.click('form[data-form=mfa-off] button[type=submit]'); W(1200); log('2FA off: ' + toast())
    p.click('[data-act=signout-others]'); W(900); log('others: ' + toast() + ' | still in: ' + h1())
    tab('notifications'); p.click('label.ld-switch:has(input[name=n_messages])'); p.click('form[data-form=set-notify] button[type=submit]'); W(); log('notify: ' + str(p.evaluate('me().prefs.notify')))
    tab('appearance'); p.click('label.a-opt:has(input[name=theme][value=dark])'); W(); log('theme attr: ' + str(p.evaluate("document.documentElement.getAttribute('data-theme')"))); shot('s4-dark')
    p.click('label.a-opt:has(input[name=theme][value=system])'); W()
    tab('privacy')
    with p.expect_download() as dl: p.click('[data-act=export-data]')
    log('export: ' + dl.value.suggested_filename)
    p.fill('#dr-r', 'Testing'); p.click('form[data-form=delete-request] button[type=submit]'); W(); log('closure: ' + toast())
    # Pro
    role('pro'); signup('Sam Patel', 'sam@example.test', 'ProPass2026')
    p.evaluate("() => patchDoc('pros', S.proId, { name: 'Sam Patel', onboarding: { status: 'SUBMITTED', step: 7 }, status: 'PENDING', skills: ['CHECK_IN'], coverage: ['BA2'], availability: { days: [1,2], slots: ['morning'] } })"); W()
    p.click('.a-side [data-go=settings]'); W(); log('pro settings tabs: ' + ', '.join(p.locator('.a-settab').all_inner_texts()))
    tab('work'); p.check('input[name=slots][value=evening]'); p.click('form[data-form=pro-profile] button[type=submit]'); W(); log('pro slots: ' + str(p.evaluate('meP().availability.slots')))
    tab('payouts'); p.fill('#po-l', '4321'); p.click('form[data-form=set-payout] button[type=submit]'); W(); log('payout: ' + p.evaluate('meP().payout.last4'))
    for t in ['profile', 'documents', 'security', 'notifications', 'appearance', 'privacy']: tab(t)
    shot('s5-pro')
    # Admin
    role('admin'); opt(p, '#au-name', 'Ops'); p.fill('#au-email', 'ops@listd.test'); p.fill('#au-password', 'Admin2026!'); opt(p, '#au-confirm', 'Admin2026!'); p.click('form[data-form=auth-admin-setup] button[type=submit]'); W(1200)
    p.fill('#au-code', p.evaluate('() => totp(S.auth.secret)')); p.click('form[data-form=auth-mfa-setup] button[type=submit]'); W(900)
    p.click('.a-side [data-go=settings]'); W(); log('admin settings tabs: ' + ', '.join(p.locator('.a-settab').all_inner_texts()))
    tab('security'); log('admin 2FA locked on: checked=%s disabled=%s' % (p.locator('[data-twofa]').is_checked(), p.locator('[data-twofa]').is_disabled()))
    p.set_viewport_size({'width': 390, 'height': 844}); W(); shot('s6-mobile')
    print('ERRORS', errs); br.close()
